-- ClipForge schema v1.
--
-- Tenancy: every business row carries workspace_id so a single deployment can later host many
-- agencies (SaaS) with row-level scoping; today one workspace = one agency.
-- IDs are UUIDv7 generated by the application (time-ordered => append-friendly B-trees);
-- gen_random_uuid() is only a fallback for manual inserts.

CREATE TABLE workspaces (
    id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    name        text NOT NULL,
    created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE users (
    id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id   uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    email          text NOT NULL,
    name           text NOT NULL DEFAULT '',
    password_hash  text NOT NULL,
    role           text NOT NULL DEFAULT 'editor' CHECK (role IN ('owner', 'admin', 'editor')),
    is_active      boolean NOT NULL DEFAULT true,
    created_at     timestamptz NOT NULL DEFAULT now(),
    last_login_at  timestamptz
);
CREATE UNIQUE INDEX users_email_key ON users (lower(email));
CREATE INDEX users_workspace_idx ON users (workspace_id);

-- Opaque, revocable sessions. Only a SHA-256 of the cookie token is stored.
CREATE TABLE sessions (
    id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id       uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    token_hash    bytea NOT NULL UNIQUE,
    created_at    timestamptz NOT NULL DEFAULT now(),
    expires_at    timestamptz NOT NULL,
    last_seen_at  timestamptz NOT NULL DEFAULT now(),
    user_agent    text,
    ip            text
);
CREATE INDEX sessions_user_idx ON sessions (user_id);
CREATE INDEX sessions_expires_idx ON sessions (expires_at);

-- A project is one client / creator / campaign. settings holds its brand kit and clip rules.
CREATE TABLE projects (
    id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id  uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    name          text NOT NULL,
    settings      jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_by    uuid REFERENCES users(id) ON DELETE SET NULL,
    created_at    timestamptz NOT NULL DEFAULT now(),
    updated_at    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX projects_workspace_idx ON projects (workspace_id, created_at DESC);

-- A long-form source video (imported from a link or uploaded).
CREATE TABLE videos (
    id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id       uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    project_id         uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    source_type        text NOT NULL CHECK (source_type IN ('url', 'upload')),
    source_url         text,
    import_options     jsonb NOT NULL DEFAULT '{}'::jsonb,
    title              text NOT NULL DEFAULT '',
    platform           text,
    external_id        text,
    uploader           text,
    status             text NOT NULL DEFAULT 'queued' CHECK (status IN
                         ('queued', 'downloading', 'processing', 'transcribing', 'analyzing', 'ready', 'failed')),
    progress           real NOT NULL DEFAULT 0,
    error              text,
    duration_ms        integer,
    width              integer,
    height             integer,
    fps                real,
    size_bytes         bigint,
    has_audio          boolean,
    language           text,
    transcript_source  text CHECK (transcript_source IN ('whisper', 'captions')),
    -- storage keys of derived artifacts: source, playback, poster, audio, timeline, transcript
    assets             jsonb NOT NULL DEFAULT '{}'::jsonb,
    -- trimmed platform metadata: chapters, view_count, upload_date, heatmap availability...
    meta               jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_by         uuid REFERENCES users(id) ON DELETE SET NULL,
    created_at         timestamptz NOT NULL DEFAULT now(),
    updated_at         timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX videos_project_idx ON videos (project_id, created_at DESC);
CREATE INDEX videos_workspace_status_idx ON videos (workspace_id, status);

-- A clip is a time range of a video plus edit settings. AI suggestions and manual clips share
-- the table; `status` tracks the editorial decision.
CREATE TABLE clips (
    id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id     uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    project_id       uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    video_id         uuid NOT NULL REFERENCES videos(id) ON DELETE CASCADE,
    origin           text NOT NULL CHECK (origin IN ('ai', 'manual')),
    status           text NOT NULL DEFAULT 'suggested' CHECK (status IN ('suggested', 'saved', 'discarded')),
    start_ms         integer NOT NULL CHECK (start_ms >= 0),
    end_ms           integer NOT NULL,
    title            text NOT NULL DEFAULT '',
    hook             text,
    reason           text,
    hashtags         text[] NOT NULL DEFAULT '{}',
    score            smallint CHECK (score BETWEEN 0 AND 100),
    score_breakdown  jsonb NOT NULL DEFAULT '{}'::jsonb,
    edit             jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_by       uuid REFERENCES users(id) ON DELETE SET NULL,
    created_at       timestamptz NOT NULL DEFAULT now(),
    updated_at       timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT clips_range_chk CHECK (end_ms > start_ms)
);
CREATE INDEX clips_video_idx ON clips (video_id, start_ms);
CREATE INDEX clips_project_status_idx ON clips (project_id, status, created_at DESC);

-- A render is an immutable export of a clip. `spec` snapshots every edit setting at request
-- time so later edits never change an already-delivered file.
CREATE TABLE renders (
    id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id   uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    project_id     uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    clip_id        uuid NOT NULL REFERENCES clips(id) ON DELETE CASCADE,
    status         text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'running', 'done', 'failed')),
    progress       real NOT NULL DEFAULT 0,
    spec           jsonb NOT NULL,
    output_key     text,
    thumbnail_key  text,
    size_bytes     bigint,
    duration_ms    integer,
    width          integer,
    height         integer,
    error          text,
    created_by     uuid REFERENCES users(id) ON DELETE SET NULL,
    created_at     timestamptz NOT NULL DEFAULT now(),
    started_at     timestamptz,
    finished_at    timestamptz
);
CREATE INDEX renders_clip_idx ON renders (clip_id, created_at DESC);
CREATE INDEX renders_project_idx ON renders (project_id, created_at DESC);

-- Where a clip was published (TikTok, Shorts, Reels, X...). Views drive agency revenue
-- (campaigns pay per 1,000 views), so stats are refreshed periodically by a worker.
CREATE TABLE posts (
    id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id      uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    project_id        uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    clip_id           uuid NOT NULL REFERENCES clips(id) ON DELETE CASCADE,
    platform          text NOT NULL,
    url               text NOT NULL,
    account           text,
    views             bigint,
    likes             bigint,
    comments          bigint,
    stats_error       text,
    stats_updated_at  timestamptz,
    created_by        uuid REFERENCES users(id) ON DELETE SET NULL,
    created_at        timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX posts_project_idx ON posts (project_id, created_at DESC);
CREATE INDEX posts_clip_idx ON posts (clip_id);
CREATE UNIQUE INDEX posts_url_key ON posts (workspace_id, url);
CREATE INDEX posts_stats_idx ON posts (stats_updated_at NULLS FIRST);

-- Durable job queue (FOR UPDATE SKIP LOCKED). Enqueueing happens in the same transaction
-- as the business write, so a video row can never exist without its ingest job.
CREATE TABLE jobs (
    id            bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    queue         text NOT NULL,
    kind          text NOT NULL,
    payload       jsonb NOT NULL DEFAULT '{}'::jsonb,
    status        text NOT NULL DEFAULT 'queued'
                    CHECK (status IN ('queued', 'running', 'succeeded', 'failed', 'canceled')),
    priority      smallint NOT NULL DEFAULT 0,
    attempts      integer NOT NULL DEFAULT 0,
    max_attempts  integer NOT NULL DEFAULT 3,
    run_at        timestamptz NOT NULL DEFAULT now(),
    locked_by     text,
    locked_at     timestamptz,
    heartbeat_at  timestamptz,
    last_error    text,
    dedupe_key    text,
    workspace_id  uuid,
    created_at    timestamptz NOT NULL DEFAULT now(),
    updated_at    timestamptz NOT NULL DEFAULT now(),
    finished_at   timestamptz
);
-- Claim hot path: a small partial index over runnable rows only.
CREATE INDEX jobs_claim_idx ON jobs (queue, priority DESC, run_at, id) WHERE status = 'queued';
-- Stale-lock recovery scans only running rows.
CREATE INDEX jobs_running_idx ON jobs (heartbeat_at) WHERE status = 'running';
-- At most one live job per dedupe key (e.g. one ingest per video).
CREATE UNIQUE INDEX jobs_dedupe_idx ON jobs (dedupe_key) WHERE status IN ('queued', 'running');
-- Retention sweeps.
CREATE INDEX jobs_finished_idx ON jobs (finished_at) WHERE finished_at IS NOT NULL;
